    title: "Product Development Workshop",
  },
];

export default function Component() {
  const [events, setEvents] = useState<CalendarEvent[]>(sampleEvents);

  const handleEventAdd = (event: CalendarEvent) => {
    setEvents([...events, event]);
  };

  const handleEventUpdate = (updatedEvent: CalendarEvent) => {
    setEvents(
      events.map((event) =>
        event.id === updatedEvent.id ? updatedEvent : event,
      ),
    );
  };

  const handleEventDelete = (eventId: string) => {
    setEvents(events.filter((event) => event.id !== eventId));
  };

  return (
    <EventCalendar
      events={events}
      onEventAdd={handleEventAdd}
      onEventDelete={handleEventDelete}
      onEventUpdate={handleEventUpdate}
    />
  );
}

"use client";

// Component exports

export { AgendaView } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/agenda-view";
export { CalendarDndProvider, useCalendarDnd } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/calendar-dnd-context";
// Constants and utility exports
export * from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/constants";
export { DayView } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/day-view";
export { DraggableEvent } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/draggable-event";
export { DroppableCell } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/droppable-cell";
export { EventCalendar } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/event-calendar";
export { EventDialog } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/event-dialog";
export { EventItem } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/event-item";
export { EventsPopup } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/events-popup";
// Hook exports
export * from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/hooks/use-current-time-indicator";
export * from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/hooks/use-event-visibility";
export { MonthView } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/month-view";
// Type exports
export type { CalendarEvent, CalendarView, EventColor } from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/types";
export * from "@/components/rendyn-libraries/originui/upstream/registry/default/components/event-calendar/utils";
